using System.Text;
using Projectional.Persistence;
using Xunit;

namespace Projectional.Core.Tests;

/// <summary>
/// The corpus is the wire format written down: files the writer produced once, which now have to
/// keep loading and keep saving back to exactly the same bytes.
/// </summary>
/// <remarks>
/// <para>
/// The fixtures were generated by the writer rather than typed by hand, so they record what the
/// code does instead of what someone believed it does. That makes them useful in one direction
/// only: they may not be regenerated to make a test pass. A change that moves a byte here is a
/// change to the file format, and the fixtures are edited in the same commit that justifies it.
/// </para>
/// <para>
/// <see cref="ModelXmlTests"/> pins the layout of a document authored by hand, which catches a
/// writer that drifts in isolation. This class pins the files an existing model turns into, which
/// catches a reader and a writer that drift together.
/// </para>
/// </remarks>
public sealed class CorpusTests
{
    private static readonly string CorpusDirectory = Path.Combine(AppContext.BaseDirectory, "Corpus");

    public static TheoryData<string> Files
    {
        get
        {
            var data = new TheoryData<string>();
            foreach (var path in Directory.GetFiles(CorpusDirectory, "*.mps").Order(StringComparer.Ordinal))
            {
                data.Add(Path.GetFileName(path));
            }

            return data;
        }
    }

    [Fact]
    public void TheCorpusIsNotEmpty()
        => Assert.NotEmpty(Directory.GetFiles(CorpusDirectory, "*.mps"));

    [Theory]
    [MemberData(nameof(Files))]
    public void ReadingAndWritingAgainKeepsTheFileByteForByte(string fileName)
    {
        var stored = File.ReadAllBytes(Path.Combine(CorpusDirectory, fileName));

        var model = ModelXml.Deserialize(TestLanguage.NewProject(), Encoding.UTF8.GetString(stored));

        Assert.Equal(stored, Encoding.UTF8.GetBytes(ModelXml.Serialize(model)));
    }

    [Theory]
    [MemberData(nameof(Files))]
    public void EveryCorpusFileIsPlainLfTextWithoutABomOrATrailingNewline(string fileName)
    {
        var stored = File.ReadAllBytes(Path.Combine(CorpusDirectory, fileName));
        var text = Encoding.UTF8.GetString(stored);

        // A byte order mark or a carriage return would survive a checkout on one platform and not
        // on the other, which turns a format that looks stable into one that is stable per machine.
        Assert.NotEqual(0xEF, stored[0]);
        Assert.DoesNotContain('\r', text);

        // The writer ends the document with the closing tag; anything after it is drift.
        Assert.EndsWith("</model>", text, StringComparison.Ordinal);
    }

    [Fact]
    public void AReferenceBetweenRootsStillResolvesToTheNodeItNames()
    {
        var model = ModelXml.Deserialize(
            TestLanguage.NewProject(),
            File.ReadAllText(Path.Combine(CorpusDirectory, "payroll.mps")));

        Assert.Equal(2, model.Roots.Count);
        Assert.Same(model.Roots[1], model.Roots[0].GetReferenceTarget("tag"));
        Assert.Equal("Salary", model.Roots[0].GetReference("tag")!.Value.ResolveInfo);
    }

    [Fact]
    public void AReferenceWhoseTargetIsGoneKeepsItsResolveInfo()
    {
        var model = ModelXml.Deserialize(
            TestLanguage.NewProject(),
            File.ReadAllText(Path.Combine(CorpusDirectory, "values.mps")));

        var reference = model.Roots[0].GetReference("tag");

        Assert.Null(model.Roots[0].GetReferenceTarget("tag"));
        Assert.Equal("Gone & forgotten", reference!.Value.ResolveInfo);
    }
}
